-- Canonical location boundaries for public territorial maps.
-- Source: GeoSalvador bairros_app_dados_2010_e_2022 FeatureServer layer 0.

BEGIN;

CREATE TABLE IF NOT EXISTS public.location_boundaries (
  location_id UUID PRIMARY KEY REFERENCES public.locations(id) ON DELETE CASCADE,
  boundary JSONB NOT NULL CHECK ((boundary->>'type') IN ('Polygon', 'MultiPolygon')),
  center_lat DOUBLE PRECISION NOT NULL CHECK (center_lat BETWEEN -90 AND 90),
  center_lng DOUBLE PRECISION NOT NULL CHECK (center_lng BETWEEN -180 AND 180),
  source TEXT NOT NULL,
  source_url TEXT,
  source_object_id TEXT,
  metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_location_boundaries_source_object
  ON public.location_boundaries (source_url, source_object_id);

DROP TRIGGER IF EXISTS update_location_boundaries_updated_at ON public.location_boundaries;
CREATE TRIGGER update_location_boundaries_updated_at
  BEFORE UPDATE ON public.location_boundaries
  FOR EACH ROW
  EXECUTE FUNCTION public.update_updated_at_column();

ALTER TABLE public.location_boundaries ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Public can read location boundaries" ON public.location_boundaries;
CREATE POLICY "Public can read location boundaries"
  ON public.location_boundaries
  FOR SELECT
  TO anon, authenticated
  USING (true);

DROP POLICY IF EXISTS "Admins can manage location boundaries" ON public.location_boundaries;
CREATE POLICY "Admins can manage location boundaries"
  ON public.location_boundaries
  FOR ALL
  TO authenticated
  USING (public.is_admin(auth.uid()))
  WITH CHECK (public.is_admin(auth.uid()));

GRANT SELECT ON public.location_boundaries TO anon, authenticated;
GRANT ALL ON public.location_boundaries TO service_role;

WITH boundary_seed(geographic_path, source_object_id, center_lat, center_lng, boundary) AS (
